from collections import deque

def resolve(path, cwd, links):
    if path is None or cwd is None:
        return None

    link_count = 0

    if path.startswith('/'):
        components = deque(path.split('/'))
    else:
        components = deque(cwd.split('/') + path.split('/'))

    current = '/'

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                new_path = '/' + comp
            else:
                new_path = current + '/' + comp

            if new_path in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[new_path]
                if target.startswith('/'):
                    target_components = target.split('/')
                else:
                    dir_path = current
                    target_components = dir_path.split('/') + target.split('/')
                components.extendleft(reversed(target_components))
                # current stays same; the link is resolved via its target
            else:
                current = new_path

    if current == '':
        current = '/'

    return current

